import torch
import torch.distributed as dist
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _all_reduce(t):
    if _world_size() == 1:
        return t
    t = t.contiguous()
    dist.all_reduce(t, op=dist.ReduceOp.SUM)
    return t


def _all_gather_last_dim(t):
    ws = _world_size()
    if ws == 1:
        return t
    t = t.contiguous()
    parts = [torch.empty_like(t) for _ in range(ws)]
    dist.all_gather(parts, t)
    return torch.cat(parts, dim=-1).contiguous()


def _split_last_dim(t):
    ws = _world_size()
    if ws == 1:
        return t
    return torch.chunk(t, ws, dim=-1)[_rank()].contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce gradient."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad.clone())


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad):
        return grad


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take local slice."""

    @staticmethod
    def forward(ctx, x):
        return _all_gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take local slice along last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _all_gather_last_dim(grad)


class ColumnParallelLinear(torch.nn.Module):
    """Y = X A^T + b, with A split along the output dimension across ranks.

    Each rank holds weight of shape (out_features / world_size, in_features)
    and the matching bias shard. Outputs are all-gathered along the last dim.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        world_size = _world_size()
        rank = _rank()
        assert out_features % world_size == 0, \
            "out_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = world_size
        self.rank = rank
        self.output_size_per_partition = out_features // world_size

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), \
            "master_weight must have shape (out_features, in_features)"
        start = rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = torch.nn.Parameter(
            master_weight[start:end, :].detach().clone().contiguous()
        )

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(self.output_size_per_partition,
                            dtype=self.weight.dtype,
                            device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        local_out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(local_out)


class RowParallelLinear(torch.nn.Module):
    """Y = X A^T + b, with A split along the input dimension across ranks.

    Each rank holds weight of shape (out_features, in_features / world_size).
    Partial outputs are all-reduced (summed); the full bias is added after
    the reduction and is replicated on every rank.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        world_size = _world_size()
        rank = _rank()
        assert in_features % world_size == 0, \
            "in_features must be divisible by world_size"
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = world_size
        self.rank = rank
        self.input_size_per_partition = in_features // world_size

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), \
            "master_weight must have shape (out_features, in_features)"
        start = rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = torch.nn.Parameter(
            master_weight[:, start:end].detach().clone().contiguous()
        )

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(out_features,
                            dtype=self.weight.dtype,
                            device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already
        # partitioned input.
        if x.shape[-1] == self.in_features and self.world_size > 1:
            x = _ScatterToParallelRegion.apply(x)
        elif x.shape[-1] != self.input_size_per_partition:
            raise ValueError(
                f"Expected input last dim {self.in_features} or "
                f"{self.input_size_per_partition}, got {x.shape[-1]}"
            )
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
